class IdeaGenerator:
    def generate_ideas(self):
        print("Here are some ideas we came up with:")
        print("- Take a long walk and enjoy the fresh air.\n- Try finger painting or experiment with a new art medium.")
        print("I hope you find these ideas helpful and enjoyable!")
        if __name__ == "__main__":
            print("I'm not sure why, but it seems like I might be able to help with that.")
            name = input("What should we call this project?")
            if name:
                print(f"Great! Let's start a {name}!")
            else:
                print('Sorry, not sure what to do yet.')

if __name__ == '__main__':
    # This will only run if the Python file is executed directly (rather than imported).
    IdeaGenerator().generate_ideas()
